declare_rule! {
    /// Disallow the use of yoda expressions.
    ///
    /// A yoda expression is a programming style where, given a binary operation, the "static" part
    /// of the binary operation is placed on the left-hand side.
    /// This rule **forbids** the use of yoda expressions and enforces the placing of the "static"
    /// part of the binary operations on the right-hand side.
    ///
    /// ## Exceptions
    ///
    /// Range expressions like `0 < value && value < 1` or `value <= 0 || 1 <= value` are allowed.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// if ("red" == value) {}
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// if (true === value) {}
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// if (5 != value) {}
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// if (value === "red") {}
    /// ```
    ///
    /// ```js
    /// if (value === value) {}
    /// ```
    ///
    /// ```js
    /// if (value != 5) {}
    /// ```
    ///
    /// ```js
    /// if (0 < value && value < 1) {}
    /// ```
    ///
    /// ## Resources
    /// - [Wikipedia definition](https://en.wikipedia.org/wiki/Yoda_conditions)
    ///
    pub NoYodaExpression {
        version: "next",
        name: "noYodaExpression",
        language: "js",
        sources: &[RuleSource::Eslint("yoda")],
        recommended: false,
        fix_kind: FixKind::Safe,
    }
}

impl Rule for NoYodaExpression {
    type Query = Ast<JsBinaryExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let binary_expression = ctx.query();

        let is_yoda = binary_expression.is_comparison_operator()
            && is_literal_expression(&binary_expression.left().ok()?)
            && !is_literal_expression(&binary_expression.right().ok()?)
            && !is_range_assertion(binary_expression);

        is_yoda.then_some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Avoid the use of yoda expressions."
                },
            )
            .note(markup! {
                "Yoda expressions can be confusing to some people, invert the expression operands for better readability."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
        let node = ctx.query();
        let flipped = flip_yoda_expression(node)?;

        let mut mutation = ctx.root().begin();
        mutation.replace_node_discard_trivia(node.clone(), flipped);

        Some(JsRuleAction::new(
            ActionCategory::QuickFix,
            ctx.metadata().applicability(),
            markup! { "Flip the operators of the expression." }.to_owned(),
            mutation,
        ))
    }
}

/// Determines whether an expression is a literal value.
///
/// String, number, boolean, null, bigint and regex literals are considered
/// literals. A template literal is only considered a literal when it does not
/// contain any interpolation.
fn is_literal_expression(expression: &AnyJsExpression) -> bool {
    match expression {
        AnyJsExpression::AnyJsLiteralExpression(_) => true,
        AnyJsExpression::JsTemplateExpression(template) => {
            template.tag().is_none()
                && template.elements().iter().all(|element| {
                    matches!(element, AnyJsTemplateElement::JsTemplateChunkElement(_))
                })
        }
        _ => false,
    }
}

/// Checks whether the binary expression is part of a range assertion, such as
/// `0 < value && value < 1` or `value < 0 || 1 < value`, in which case the yoda
/// expression is allowed because it improves readability.
fn is_range_assertion(node: &JsBinaryExpression) -> bool {
    is_range_assertion_impl(node).unwrap_or(false)
}

fn is_range_assertion_impl(node: &JsBinaryExpression) -> Option<bool> {
    let mut parent = node.syntax().parent()?;
    while JsParenthesizedExpression::can_cast(parent.kind()) {
        parent = parent.parent()?;
    }

    let logical = JsLogicalExpression::cast(parent)?;
    if !matches!(
        logical.operator().ok()?,
        JsLogicalOperator::LogicalAnd | JsLogicalOperator::LogicalOr
    ) {
        return Some(false);
    }

    let left = logical.left().ok()?.omit_parentheses();
    let right = logical.right().ok()?.omit_parentheses();

    let left = JsBinaryExpression::cast(left.into_syntax())?;
